#include <vector>
#include <algorithm>
#define main legacy_main
#include "../overlap-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(){int n=262144,repeats=12,inner=5;int *hin[4],*hout[4],*din[4],*dout[4];cudaStream_t st[4];for(int s=0;s<4;s++){CK(cudaHostAlloc(&hin[s],n*4,cudaHostAllocDefault));CK(cudaHostAlloc(&hout[s],n*4,cudaHostAllocDefault));CK(cudaMalloc(&din[s],n*4));CK(cudaMalloc(&dout[s],n*4));CK(cudaStreamCreate(&st[s]));for(int i=0;i<n;i++)hin[s][i]=(i*13+(s+1)*7)%257-128;CK(cudaMemcpy(din[s],hin[s],n*4,cudaMemcpyHostToDevice));CK(cudaMemset(dout[s],0,n*4));}
auto pipeline=[&](int used){int current=0;for(int rep=0;rep<repeats;rep++){int next=(current+1)%used;incKernel<<<n/256,256,0,st[current]>>>(dout[current],din[current],n,inner);CK(cudaMemcpyAsync(din[next],hin[next],n*4,cudaMemcpyHostToDevice,st[next]));CK(cudaMemcpyAsync(hout[current],dout[current],n*4,cudaMemcpyDeviceToHost,st[current]));current=next;}CK(cudaDeviceSynchronize());};pipeline(4);bool all=true;for(int trial=1;trial<=5;trial++){double times[2]={};std::vector<int>output;bool ok=true;int ma=0,mi=0;for(int used:{1,4}){for(int s=0;s<4;s++){CK(cudaMemcpy(din[s],hin[s],n*4,cudaMemcpyHostToDevice));CK(cudaMemset(dout[s],0,n*4));memset(hout[s],0,n*4);}CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();pipeline(used);times[mi++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;for(int s=0;s<4;s++)for(int i=0;i<n;i++){int expected=s<used?hin[s][i]+inner:0;ma=std::max(ma,abs(hout[s][i]-expected));output.push_back(hout[s][i]);}ok=ma==0;}all&=ok;char file[100];sprintf(file,"overlap_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"sum_one_and_four_stream_pinned_H2D_kernel_D2H_pipeline_per_frame\",\"jit_excluded\":true,\"internal_repeats\":%d,\"stream_mode_times_seconds\":[%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",int(output.size()),ma,repeats,times[0],times[1],file,int(output.size()));}for(int s=0;s<4;s++){CK(cudaFreeHost(hin[s]));CK(cudaFreeHost(hout[s]));CK(cudaFree(din[s]));CK(cudaFree(dout[s]));CK(cudaStreamDestroy(st[s]));}puts(all?"PASS":"FAIL");return all?0:1;}
